from django.contrib import admin, messagesfrom django.db import transactionfrom django.utils.html import format_htmlfrom django.utils.safestring import mark_safefrom .models import AndroidApp@admin.register(AndroidApp)class AndroidAppAdmin(admin.ModelAdmin):    list_display = (        "version_badge",        "version_code",        "active_badge",        "force_badge",        "downloads",        "apk_size_display",        "apk_file",        "created_at",    )    list_display_links = ("version_badge",)    search_fields = (        "version_name",        "release_notes",    )    list_filter = (        "is_active",        "force_update",        "created_at",    )    readonly_fields = (        "apk_download",        "apk_size_display",        "download_count",        "created_at",        "updated_at",    )    fieldsets = (        (            "Version Information",            {                "fields": (                    "version_name",                    "version_code",                )            },        ),        (            "APK Upload",            {                "fields": (                    "apk",                    "apk_download",                    "apk_size_display",                )            },        ),        (            "Update Settings",            {                "fields": (                    "is_active",                    "force_update",                )            },        ),        (            "Release Notes",            {                "fields": (                    "release_notes",                )            },        ),        (            "Statistics",            {                "fields": (                    "download_count",                    "created_at",                    "updated_at",                )            },        ),    )    # Completely remove all mass-selection actions since there is only 1 object    actions = None    # ======================================================    # STRICT SINGLE-ITEM ENFORCEMENT RULES    # ======================================================    def has_add_permission(self, request):        """        Removes the 'Add' button entirely if an entry already exists.        """        if AndroidApp.objects.exists():            return False        return super().has_add_permission(request)    def has_delete_permission(self, request, obj=None):        """        Optional: Prevents deleting the single item to ensure configuration         data isn't cleared completely. (Change to True if you want to allow it)        """        return False    def save_model(self, request, obj, form, change):        """        Ensures strict database single-record atomic integrity during creation.        """        with transaction.atomic():            # If creating a completely new item, wipe any stray historic records first            if not change:                AndroidApp.objects.all().delete()                        # Enforce that the single row is always marked active            obj.is_active = True            super().save_model(request, obj, form, change)    # ======================================================    # FORMATTING DISPLAY LAYOUTS    # ======================================================    @admin.display(description="Version", ordering="version_code")    def version_badge(self, obj):        return format_html(            '<strong style="color:#2563eb;">{}</strong>',            obj.version_name,        )    @admin.display(description="Status")    def active_badge(self, obj):        if obj.is_active:            return mark_safe('<span style="color:green;font-weight:bold;">● Active</span>')        return mark_safe('<span style="color:red;font-weight:bold;">Inactive</span>')    @admin.display(description="Force Update")    def force_badge(self, obj):        if obj.force_update:            return mark_safe('<span style="color:red;font-weight:bold;">YES</span>')        return mark_safe('<span style="color:green;font-weight:bold;">NO</span>')    @admin.display(description="Downloads", ordering="download_count")    def downloads(self, obj):        return obj.download_count    @admin.display(description="APK Size")    def apk_size_display(self, obj):        if not obj.apk:            return "-"        try:            size = obj.apk.size            if size < 1024:                return f"{size} B"            if size < 1024 * 1024:                return f"{size / 1024:.2f} KB"            if size < 1024 * 1024 * 1024:                return f"{size / (1024 * 1024):.2f} MB"            return f"{size / (1024 * 1024 * 1024):.2f} GB"        except Exception:            return "-"    @admin.display(description="APK")    def apk_file(self, obj):        if obj.apk:            return format_html(                '<a href="{}" target="_blank">Download APK</a>',                obj.apk.url,            )        return "-"    @admin.display(description="APK Download")    def apk_download(self, obj):        if obj.pk and obj.apk:            return format_html(                '<a class="button" href="{}" target="_blank">Download APK</a>',                obj.apk.url,            )        return "Upload APK first."